pub(crate) fn in_lower(cp: i32) -> i32 {
    if (cp >= 65) && (cp <= 90) {
        return cp + 32;
    }
    return cp;
}
pub fn in_lang(loc: &mut crate::port::Cells) -> i32 {
    // The language of a locale tag held as code points (`en`, `en-US`, `DE_ch`): LG_NONE for no tag, else an LG_
    // code, LG_OTHER for a language without a table.
    let n: i32 = crate::port::cells_len(loc);
    if n < 2 {
        return LG_NONE;
    }
    let a: i32 = in_lower(crate::port::cells_at(loc, 0));
    let b: i32 = in_lower(crate::port::cells_at(loc, 1));
    let mut c: i32 = 45;
    if n > 2 {
        c = crate::port::cells_at(loc, 2);
    }
    if (c != 45) && (c != 95) {
        return LG_OTHER;
    }
    if (a == 101) && (b == 110) {
        return LG_EN;
    }
    if (a == 100) && (b == 101) {
        return LG_DE;
    }
    if (a == 102) && (b == 114) {
        return LG_FR;
    }
    if (a == 101) && (b == 115) {
        return LG_ES;
    }
    if (a == 112) && (b == 116) {
        return LG_PT;
    }
    if (a == 105) && (b == 116) {
        return LG_IT;
    }
    if (a == 110) && (b == 108) {
        return LG_NL;
    }
    return LG_OTHER;
}
pub(crate) fn in_one_letter(lang: i32, cp: i32) -> bool {
    // Is the upper-case code point cp a word of its own in language `lang` (the union of the tables when LG_NONE or
    // LG_OTHER)?
    let mut i: i32 = 0;
    let mut cur: i32 = -1;
    while i < 38 {
        let v: i32 = IN_ONE[(i) as usize];
        if cur < 0 {
            cur = v;
        } else if v == 0 {
            cur = -1;
        } else if (v == cp) && ((cur == lang) || ((lang == LG_NONE) || (lang == LG_OTHER))) {
            return 1 == 1;
        }
        i += 1;
    }
    return 0 == 1;
}
pub(crate) fn in_follows(lang: i32, kind: i32, letter: i32, et: &mut crate::port::Cells, ts: i32, tl: i32) -> bool {
    // Is the word et[ts, ts+tl) (lower-cased) in the list `kind` (1 the words a one-letter word is followed by, 2 the
    // rest of a word the letter begins) for (lang, letter)?
    let n: i32 = 685;
    let mut i: i32 = 0;
    let mut inlang: i32 = 0;
    let mut inlet: i32 = 0;
    let mut w: i32 = 0;
    let mut k: i32 = 0;
    let mut same: i32 = 0;
    while i < n {
        let v: i32 = IN_FOLLOW[(i) as usize];
        if inlang == 0 {
            if v == 0 {
                return 0 == 1;
            }
            inlang = v;
            inlet = 0;
            i += 1;
        } else if inlet == 0 {
            if v == 0 {
                inlang = 0;
                i += 1;
            } else {
                inlet = v;
                i += 1;
            }
        } else {
            if v == 0 {
                inlet = 0;
                i += 1;
            } else {
                w = v;
                if (inlang == ((lang * 10) + kind)) && (inlet == letter) && (w == tl) {
                    same = 1;
                    k = 0;
                    while k < w {
                        if IN_FOLLOW[(i + (1 + k)) as usize] != in_lower(crate::port::cells_at(et, ts + k)) {
                            same = 0;
                        }
                        k += 1;
                    }
                    if same == 1 {
                        return 1 == 1;
                    }
                }
                i += 1 + w;
            }
        }
    }
    return 0 == 1;
}
pub fn in_join(loc: &mut crate::port::Cells, cp: i32, et: &mut crate::port::Cells, ts: i32, tl: i32) -> i32 {
    // How an initial whose whole text is the code point cp (upper case or not) meets the first word of its first
    // line, et[ts, ts+tl) (an empty word is tl 0): 0 joined and sure, 1 joined and flagged low-conf, 2 a space.
    let lang: i32 = in_lang(loc);
    let mut up: i32 = cp;
    if (cp >= 97) && (cp <= 122) {
        up = cp - 32;
    }
    if !in_one_letter(lang, up) {
        return 0;
    }
    if (lang == LG_EN) && (tl > 0) {
        if in_follows(lang, 1, up, et, ts, tl) {
            return 2;
        }
        if in_follows(lang, 2, up, et, ts, tl) {
            return 0;
        }
    }
    return 1;
}
pub(crate) fn in_join_of(wd: &mut crate::port::Cells, et: &mut crate::port::Cells, lt: &mut crate::port::Cells, loc: &mut crate::port::Cells, ii: &mut crate::port::Cells, r: i32) -> i32 {
    // How the initial of row r of `ii` meets the first word of its first line: 0 joined and sure, 1 joined and
    // flagged low-conf, 2 a space. One code point: `in-join`'s table and lists. Two or more that begin with a letter or
    // digit: a whole first word (`IT`), a space, unless it is of a script written without spaces; one that begins with
    // punctuation (`“N`) is joined. A raised initial is part of its word.
    let rr: i32 = r * II_STRIDE;
    let il: i32 = crate::port::cells_at(ii, rr + II_IL);
    let ncp: i32 = crate::port::cells_at(ii, rr + II_NCP);
    let iw: i32 = crate::port::cells_at(ii, rr + II_WORD);
    let w1: i32 = ln_get(lt, crate::port::cells_at(ii, rr + II_TL), lh_first());
    if (il < 0) && (ncp < wd_get(wd, iw, hd_tlen())) {
        return 0;
    }
    let c0: i32 = in_first_cp(wd, et, iw);
    if c0 < 0 {
        return 0;
    }
    if ncp == 1 {
        return in_join(loc, c0, et, wd_get(wd, w1, hd_tstart()), wd_get(wd, w1, hd_tlen()));
    }
    if !in_alnum(c0) {
        return 0;
    }
    if in_ideo(c0) {
        return 0;
    }
    return 2;
}
pub fn in_detect(wd: &mut crate::port::Cells, gl: &mut crate::port::Cells, fo: &mut crate::port::Cells, et: &mut crate::port::Cells, npages: i32, loc: &mut crate::port::Cells, mut lt: &mut crate::port::Cells, mut sc: &mut crate::port::Cells, mut sq: &mut crate::port::Cells, mut tm: &mut crate::port::Cells, mut ii: &mut crate::port::Cells) -> i32 {
    // Every page's initials. `lt` is the lines' copy (`lc-copy`): rewritten as the header says. `ii` is the table
    // of initials (stride 12); `loc` the locale tag as code points (empty for none), which decides the join. `sc sq tm`
    // are scratch. Answers the initials found.
    let nl: i32 = crate::port::cells_len(lt) / 16;
    let mut p: i32 = 1;
    let mut r: i32 = 0;
    let mut q: i32 = 0;
    crate::port::cells_drop(ii, 0);
    // Cell 15 is this stage's alone: whatever a producer left there is cleared.
    while r < nl {
        crate::port::cells_set(lt, (r * 16) + 15, 0);
        r += 1;
    }
    while p <= npages {
        in_page(wd, gl, fo, et, lt, p, sc, sq, tm, ii);
        p += 1;
    }
    q = crate::port::cells_len(ii) / II_STRIDE;
    r = 0;
    while r < q {
        let rr: i32 = r * II_STRIDE;
        let t: i32 = crate::port::cells_at(ii, rr + II_TL);
        let jn: i32 = in_join_of(wd, et, lt, loc, ii, r);
        crate::port::cells_set(ii, rr + II_JOIN, jn);
        if (t >= 0) && (t < nl) {
            let mut v: i32 = (r + 1) * 4;
            if crate::port::cells_at(ii, rr + II_IL) < 0 {
                v += 1;
                if (crate::port::cells_at(ii, rr + II_NCP) == wd_get(wd, crate::port::cells_at(ii, rr + II_WORD), hd_tlen())) && (jn != 2) {
                    v += 2;
                }
            }
            crate::port::cells_set(lt, (t * 16) + 15, v);
        }
        r += 1;
    }
    return q;
}
pub fn in_get_ii(ii: &mut crate::port::Cells, r: i32, f: i32) -> i32 {
    return crate::port::cells_at(ii, (r * II_STRIDE) + f);
}
pub fn in_row(lt: &mut crate::port::Cells, l: i32) -> i32 {
    // The row of `ii` whose target is row l of `lt`, -1 for none.
    if (l < 0) || (((l + 1) * 16) > crate::port::cells_len(lt)) {
        return -1;
    }
    let c: i32 = crate::port::cells_at(lt, (l * 16) + 15);
    if c < 4 {
        return -1;
    }
    return (c / 4) - 1;
}
